public record FolderNode(
    string Id,
    string Label,
    string? Icon,
    bool IsLeaf,
    bool IsLoading,
    IReadOnlyList<ITreeNode<string>> Children
) : ITreeNode<string>;

public class FolderNode : ITreeNode<Guid>
{
    public Guid Id { get; init; }
    public string Label { get; init; } = default!;
    public string? Icon { get; init; }
    public bool IsLeaf { get; set; }
    public bool IsLoading { get; set; }

    private readonly List<ITreeNode<Guid>> _children = [];
    public IReadOnlyList<ITreeNode<Guid>> Children => _children;

    public void AddChild(FolderNode child) => _children.Add(child);
}

